<?php
require 'functions.php';
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
$s=$pdo->prepare('SELECT m.*,p.code,p.name,p.category,p.unit FROM stock_movements m JOIN products p ON p.id=m.product_id WHERE m.movement_date BETWEEN ? AND ? ORDER BY m.movement_date DESC,m.id DESC');$s->execute([$from,$to]);$rows=$s->fetchAll();
$in=0;$out=0;foreach($rows as $r){if($r['type']==='IN')$in+=$r['qty'];else$out+=$r['qty'];}
layoutStart('Laporan Stok','laporan');
echo '<section class="card"><div class="card-head"><h2>Filter Periode</h2><button class="btn" onclick="window.print()">Cetak</button></div><form class="filter"><label>Dari<input type="date" name="from" value="'.e($from).'"></label><label>Sampai<input type="date" name="to" value="'.e($to).'"></label><button class="btn primary">Tampilkan</button></form></section><section class="stats compact">'.statCard('Total Masuk',(string)$in,'Unit pada periode').statCard('Total Keluar',(string)$out,'Unit pada periode').statCard('Jumlah Transaksi',(string)count($rows),'Catatan aktivitas').'</section><section class="card"><div class="card-head"><h2>Rekap Transaksi</h2><span>'.e($from).' s.d. '.e($to).'</span></div><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Kode</th><th>Barang</th><th>Kategori</th><th>Masuk</th><th>Keluar</th><th>Catatan</th></tr></thead><tbody>';
foreach($rows as $r)echo '<tr><td>'.e($r['movement_date']).'</td><td>'.e($r['code']).'</td><td>'.e($r['name']).'</td><td>'.e($r['category']).'</td><td>'.($r['type']==='IN'?$r['qty']:'-').'</td><td>'.($r['type']==='OUT'?$r['qty']:'-').'</td><td>'.e($r['note']?:'-').'</td></tr>';if(!$rows)echo '<tr><td colspan="7" class="empty">Tidak ada data pada periode ini.</td></tr>';echo '</tbody></table></div></section>';layoutEnd();
